function driverFields(selectedUid='',externalName=''){let ext=admin()?`<option value="__external__" ${!selectedUid&&externalName?'selected':''}>Externer Fahrer / manuell</option>`:'';return`<label>Fahrer<select name="driverUid" required><option value="">Bitte auswählen</option>${activeDriverOptions(selectedUid)}${ext}</select></label>${admin()?`<label class="externalDriverLabel" style="display:${!selectedUid&&externalName?'block':'none'}">Name externer Fahrer<input name="externalDriver" value="${esc(externalName)}"></label>`:''}`}
function wireDriverForm(form){let select=form.elements.driverUid,label=form.querySelector('.externalDriverLabel');if(!label)return;let sync=()=>label.style.display=select.value==='__external__'?'block':'none';select.onchange=sync;sync()}
function whatsappRequestText(data){let bus=data.vehicleId?vehicles.find(v=>v.id===data.vehicleId)?.name||'Unbekannter Bus':'beliebig';return`VfR Taxi | Neue Busanfrage\n\nMannschaft: ${data.team}\nDatum: ${fmt(data.date)}${data.endDate!==data.date?` bis ${fmt(data.endDate)}`:''}\nZeit: ${data.from}–${data.to} Uhr\nAngefragt von: ${data.trainer}\nFahrer: ${data.driverName}${data.driverType==='external'?' (extern)':''}\nWunschbus: ${bus}\nZiel: ${data.purpose}`}
function requestSavedDialog(data,conflict){let url=`https://wa.me/${WHATSAPP_ADMIN_NUMBER}?text=${encodeURIComponent(whatsappRequestText(data))}`;open(`<div class="saveSuccess"><div class="saveSuccessIcon">✓</div><h2>Busanfrage erfolgreich gespeichert</h2><p>Die Anfrage wurde an die Busverwaltung übermittelt.${conflict?'<br><b>Hinweis:</b> Der gewünschte Bus hat eine zeitliche Überschneidung.':''}</p><a class="whatsappAdminBtn" id="whatsappAdminBtn" href="${esc(url)}" target="_blank" rel="noopener">Admin per WhatsApp informieren</a><button type="button" class="secondaryCloseBtn" id="requestSuccessClose">Schließen</button></div>`);$('#requestSuccessClose').onclick=()=>modal.close()}
function requestForm(){open(`<h2>Neue Busanfrage</h2><form id="rf" class="requestForm"><label>Mannschaft<input name="team" required></label><div class="personBlock"><label>Anfragensteller<input value="${esc(me.name)}" disabled></label>${driverFields(me.uid,'')}</div><div class="compactPair"><label>Datum von<input name="date" type="date" required></label><label>Datum bis<input name="endDate" type="date" required></label></div><div class="compactPair"><label>Zeit von<input name="from" type="time" required></label><label>Zeit bis<input name="to" type="time" required></label></div><label>Buswunsch<select name="vehicle"><option value="">Bus egal</option>${vehicles.map(v=>`<option value="${v.id}">${esc(v.name)} · ${esc(v.plate)}</option>`).join('')}</select></label><label>Ort / Ziel<input name="purpose" required></label><button class="primary">Anfrage absenden</button></form>`);let form=$('#rf');wireDriverForm(form);form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form),date=f.get('date'),endDate=f.get('endDate'),from=f.get('from'),to=f.get('to'),vehicleId=String(f.get('vehicle')||'')||null;if(endDate<date)return toast('Datum bis darf nicht vor Datum von liegen.');let driver;try{driver=readDriver(f)}catch(err){return toast(err.message)}let conflict=bookingConflict(vehicleId,date,endDate,from,to);if(conflict&&!confirm(`Achtung: ${vehicles.find(v=>v.id===vehicleId)?.name||'Der gewünschte Bus'} ist im gewünschten Zeitraum bereits reserviert oder gesperrt.\n\nAnfrage mit diesem Buswunsch trotzdem speichern?`))return;let btn=form.querySelector('button.primary'),data={team:String(f.get('team')||'').trim(),trainer:me.name,trainerUid:me.uid,...driver,date,endDate,from,to,vehicleId,purpose:String(f.get('purpose')||'').trim(),status:'requested'};try{btn.disabled=true;let ref=await addDoc(collection(db,'bookings'),{...data,createdAt:serverTimestamp()});let saved=await getDoc(ref);if(!saved.exists())throw Error('Die gespeicherte Anfrage konnte nicht bestätigt werden.');requestSavedDialog(data,conflict)}catch(err){btn.disabled=false;toast('Speichern fehlgeschlagen: '+(err?.message||'Unbekannter Fehler'))}}}
function editRequestForm(id){let x=bookings.find(b=>b.id===id);if(!x||x.status!=='requested'||(!admin()&&x.trainerUid!==me.uid))return toast('Nur eigene offene Anfragen können bearbeitet werden.');open(`<h2>Busanfrage bearbeiten</h2><form id="erf" class="requestEditForm"><label>Mannschaft<input name="team" value="${esc(x.team||'')}" required></label><div class="personBlock"><label>Anfragensteller<input value="${esc(x.trainer||me.name)}" disabled></label>${driverFields(x.driverUid||'',x.driverType==='external'?x.driverName||'':'')}</div><div class="compactPair"><label>Datum von<input name="date" type="date" value="${esc(x.date||'')}" required></label><label>Datum bis<input name="endDate" type="date" value="${esc(x.endDate||x.date||'')}" required></label></div><div class="compactPair"><label>Zeit von<input name="from" type="time" value="${esc(x.from||'')}" required></label><label>Zeit bis<input name="to" type="time" value="${esc(x.to||'')}" required></label></div><label>Buswunsch<select name="vehicle"><option value="">Bus egal</option>${vehicles.map(v=>`<option value="${v.id}" ${x.vehicleId===v.id?'selected':''}>${esc(v.name)} · ${esc(v.plate)}</option>`).join('')}</select></label><label>Ort / Ziel<input name="purpose" value="${esc(x.purpose||'')}" required></label><button class="primary">Änderungen speichern</button></form>`);let form=$('#erf');wireDriverForm(form);form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form),date=f.get('date'),endDate=f.get('endDate'),from=f.get('from'),to=f.get('to'),vehicleId=String(f.get('vehicle')||'')||null;if(endDate<date)return toast('Datum bis darf nicht vor Datum von liegen.');let driver;try{driver=readDriver(f)}catch(err){return toast(err.message)}let conflict=bookingConflict(vehicleId,date,endDate,from,to,id);if(conflict&&!confirm(`Achtung: ${vehicles.find(v=>v.id===vehicleId)?.name||'Der gewünschte Bus'} ist im gewünschten Zeitraum bereits reserviert oder gesperrt.\n\nÄnderung trotzdem speichern?`))return;let btn=form.querySelector('button[type="submit"],button.primary');try{btn.disabled=true;let payload={team:String(f.get('team')||'').trim(),date,endDate,from,to,vehicleId,purpose:String(f.get('purpose')||'').trim(),driverUid:driver.driverUid||null,driverName:driver.driverName,driverType:driver.driverType,updatedAt:serverTimestamp(),updatedByUid:me.uid,updatedByName:me.name};await updateDoc(doc(db,'bookings',id),payload);let saved=await getDoc(doc(db,'bookings',id));if(!saved.exists())throw Error('Buchung nicht mehr vorhanden.');let d=saved.data();if(String(d.vehicleId||'')!==String(vehicleId||'')||String(d.driverUid||'')!==String(driver.driverUid||'')||String(d.driverName||'')!==String(driver.driverName||''))throw Error('Buswunsch oder Fahrer wurde nicht korrekt gespeichert.');modal.close();toast('Anfrage geändert und gespeichert')}catch(err){btn.disabled=false;toast('Ändern fehlgeschlagen: '+(err?.message||'Unbekannter Fehler'))}}}
function conflictHint(c){if(!c)return'';return`${c.status==='blocked'?'Gesperrt':'Belegt'}: ${fmt(c.date)}${(c.endDate||c.date)!==c.date?` bis ${fmt(c.endDate)}`:''} · ${c.from||'00:00'}–${c.to||'23:59'} Uhr${c.team?` · ${c.team}`:''}`}
function assignmentButtons(x){return vehicles.map(v=>{let c=bookingConflict(v.id,x.date,x.endDate||x.date,x.from,x.to,x.id),off=!!c;return`<div class="assignChoice"><button class="${x.vehicleId===v.id?'wishBus':''} ${off?'assignmentBlocked':''}" data-a="${x.id}" data-v="${v.id}" ${off?'disabled aria-disabled="true"':''}>${esc(v.name)} ${off?'belegt':'zuweisen'}</button>${off?`<small>${esc(conflictHint(c))}</small>`:''}</div>`}).join('')}
function requestView(){let xs=bookings.filter(x=>x.status==='requested').sort((a,b)=>createdMs(a)-createdMs(b));cont.innerHTML=`<div class="row"><div><h2>Busanfragen</h2><p>Für alle sichtbar.</p></div><button class="primary" style="width:auto" id="nr">+ Anfrage</button></div><div class="list">${xs.map(x=>`<div class="item" style="border-color:#f5c842"><span class="pill requested">ANGEFRAGT</span><h3>${esc(x.team)} · ${esc(x.purpose)}</h3><p>${fmt(x.date)}${(x.endDate||x.date)!==x.date?` bis ${fmt(x.endDate)}`:''} · ${esc(x.from)}–${esc(x.to)}<br>Angefragt von: <b>${esc(x.trainer)}</b><br>Fahrer: <b>${esc(x.driverName||x.trainer||'nicht angegeben')}${x.driverType==='external'?' (extern)':''}</b><br>Buswunsch: ${x.vehicleId?esc(vehicles.find(v=>v.id===x.vehicleId)?.name):'beliebig'}<br><span class="requestReceived">Angefragt: <b>${esc(fmtTimestamp(x.createdAt))}</b></span></p><div class="actions assignmentActions">${admin()?assignmentButtons(x):''}${admin()||x.trainerUid===me.uid?`<button class="editRequestBtn" data-e="${x.id}">Bearbeiten</button>`:''}${admin()||x.trainerUid===me.uid?`<button class="dangerBtn" data-d="${x.id}">Zurückziehen</button>`:''}</div></div>`).join('')||'<p>Keine offenen Anfragen.</p>'}</div>`;$('#nr').onclick=requestForm;cont.querySelectorAll('[data-a]:not(:disabled)').forEach(b=>b.onclick=async()=>{let x=bookings.find(z=>z.id===b.dataset.a),c=bookingConflict(b.dataset.v,x.date,x.endDate||x.date,x.from,x.to,x.id);if(c){toast(`${vehicles.find(v=>v.id===b.dataset.v)?.name||'Bus'} ist in diesem Zeitraum bereits reserviert oder gesperrt.`);render();return}await updateDoc(doc(db,'bookings',b.dataset.a),{vehicleId:b.dataset.v,status:'reserved',approvedBy:me.uid,approvedAt:serverTimestamp()});toast('Bus zugewiesen')});cont.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>editRequestForm(b.dataset.e));cont.querySelectorAll('[data-d]').forEach(b=>b.onclick=async()=>{if(!confirm('Anfrage wirklich zurückziehen?'))return;try{await deleteDoc(doc(db,'bookings',b.dataset.d));toast('Anfrage zurückgezogen')}catch(x){toast(x.message)}})}
let calendarMode='month',calendarCursor=new Date();calendarCursor.setHours(12,0,0,0);
function bookingOnDay(b,day){return b.date<=day&&(b.endDate||b.date)>=day}
function eventLabel(b){let bus=b.vehicleId?vehicles.find(v=>v.id===b.vehicleId)?.name:'Bus offen';return`${bus||'Bus'} · ${b.team}`}
function calendarState(b){if(b.status==='blocked')return'blocked';if(b.status==='requested')return'requested';let t=tripForBooking(b.id),end=bookingTimes(b)[1].getTime(),now=Date.now();if(t?.status==='auto-closed')return'autoClosed';if(t?.status==='active')return now>=end?'overdue':'inuse';if(now>=end)return'past';return'reserved'}
function legendRow(cls,title,text){return`<div class="legendRow"><span class="legendSwatch ${cls}"></span><div><b>${title}</b><p>${text}</p></div></div>`}
function showLegend(){mb.innerHTML=`<div class="legendHelp"><h2>Legende und Bedienhilfe</h2><p>Gleiche Farben haben in der gesamten App dieselbe Bedeutung. Die folgenden Abschnitte nennen ausdrücklich, wo die jeweilige Kennzeichnung verwendet wird.</p><h3>Farben im Reiter „Belegung“</h3>${legendRow('requested','ANGEFRAGT','Eine Anfrage wartet noch auf die Zuweisung durch Admin. Eine offene Anfrage blockiert keinen Bus.')}${legendRow('reserved','RESERVIERT','Der Bus ist für den angezeigten Zeitraum verbindlich reserviert. Die Fahrt wurde noch nicht gestartet.')}${legendRow('inuse','IN NUTZUNG','Die Fahrt wurde gestartet und läuft aktuell.')}${legendRow('overdue','ÜBERFÄLLIG','Die Reservierungszeit ist abgelaufen, die gestartete Fahrt wurde aber noch nicht beendet. „Fahrt beenden“ bleibt verfügbar.')}${legendRow('past','VERGANGEN','Die Reservierung liegt in der Vergangenheit und es besteht keine aktive Fahrt mehr. Dazu gehören normal beendete und nie gestartete, abgelaufene Reservierungen.')}${legendRow('autoClosed','NICHT ORDNUNGSGEMÄSS ABGESCHLOSSEN','Die Fahrt wurde beim Start einer nachfolgenden Fahrt automatisch abgeschlossen. In den Tagesdetails stehen Anfragensteller, eingetragener Fahrer, Abschlusszeit, übernommener Kilometerstand und die Person, die den automatischen Abschluss ausgelöst hat.')}${legendRow('blocked','GESPERRT / WERKSTATT','Der Bus steht im angegebenen Zeitraum nicht zur Verfügung.')}<h3>Farben im Reiter „Fahrzeuge“</h3>${legendRow('free','FREI','Der Bus ist verfügbar. „Frei bis …“ zeigt die nächste verbindliche Belegung.')}${legendRow('reserved','RESERVIERT','Die Reservierungszeit läuft, die Fahrt wurde noch nicht gestartet.')}${legendRow('inuse','IN NUTZUNG','Die Fahrt wurde gestartet und der Bus wird aktuell genutzt.')}${legendRow('overdue','ÜBERFÄLLIG','Das Reservierungsende ist überschritten, die Fahrt ist aber weiterhin aktiv.')}${legendRow('blocked','GESPERRT / WERKSTATT','Der Bus kann nicht genutzt oder zugewiesen werden.')}<h3>Fahrt starten</h3>${legendRow('free','GRÜNER STARTBUTTON','Die Fahrt darf gestartet werden. Der Button wird frühestens 24 Stunden vor Reservierungsbeginn aktiv und verschwindet nach Reservierungsende, wenn die Fahrt nicht gestartet wurde.')}${legendRow('overdue','ORANGER STARTBUTTON','Der Start ist möglich, aber für denselben Bus existiert noch eine aktive vorherige Fahrt. Nach Bestätigung wird die vorherige Fahrt automatisch abgeschlossen und dokumentiert; der neue Abfahrts-KM-Stand wird als End-KM-Stand der vorherigen Fahrt übernommen.')}<p><b>Startberechtigt:</b> Admin, unveränderbarer Anfragensteller und eingetragener registrierter Fahrer.</p><h3>Fahrt beenden</h3><p>Nach dem Start können Admin, Anfragensteller und eingetragener Fahrer die Fahrt beenden. Es ist egal, wer gestartet hat. Auch bei „ÜBERFÄLLIG“ bleibt der Button verfügbar. Sobald eine Person beendet, verschwindet der Button bei allen Beteiligten.</p></div>`;if(!modal.open)modal.showModal()}

function autoClosedInfo(b){let t=tripForBooking(b.id);if(t?.status!=='auto-closed')return'';return`<div class="autoClosedDetails"><b>⚠ Nicht ordnungsgemäß abgeschlossen</b><br>Anfragensteller: <b>${esc(t.autoCloseTrainerName||t.trainer||b.trainer||'Unbekannt')}</b><br>Eingetragener Fahrer: <b>${esc(t.autoCloseDriverName||t.driverName||b.driverName||'Unbekannt')}</b><br>Automatisch abgeschlossen: <b>${esc(fmtTimestamp(t.endedAt||t.updatedAt))}</b><br>KM Ankunft automatisch übernommen: <b>${Number(t.kmEnd||0).toLocaleString('de-DE')} km</b><br>Ausgelöst durch: <b>${esc(t.autoCloseTriggeredBy||t.updatedByName||'Unbekannt')}</b><br><small>Grund: Start der nächsten Fahrt</small></div>`}
function calendarView(){calendarMode='month';monthCalendarView()}
function calendarShell(title,body){
  cont.innerHTML=`<div class="legendBar"><button id="legendMode" type="button">Legende</button></div><div class="calendarTools"><button id="prev">‹</button><h2>${title}</h2><button id="next">›</button></div><div class="jumpRow"><input id="jumpDate" type="month" value="${calendarCursor.getFullYear()}-${String(calendarCursor.getMonth()+1).padStart(2,'0')}"><button id="today" class="primary">Heute</button></div>${body}`;
  $('#legendMode').onclick=showLegend;
  $('#jumpDate').onchange=e=>{let[y,m]=e.target.value.split('-').map(Number);calendarCursor=new Date(y,m-1,1,12);calendarView()};
  $('#today').onclick=()=>{calendarCursor=new Date();calendarCursor.setHours(12,0,0,0);calendarView()};
}
function monthCalendarView(){
  let y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),first=new Date(y,m,1,12),offset=(first.getDay()+6)%7,start=add(first,-offset),days=Array.from({length:42},(_,i)=>add(start,i));
  let heads=['Mo','Di','Mi','Do','Fr','Sa','So'].map(x=>`<div class="monthHead">${x}</div>`).join('');
  let cells=days.map((d,dayIndex)=>{let di=iso(d),items=bookings.filter(b=>bookingOnDay(b,di)).sort((a,b)=>String(a.vehicleId||'').localeCompare(String(b.vehicleId||''))||String(a.team||'').localeCompare(String(b.team||''))||a.date.localeCompare(b.date)),shown=items.slice(0,3),outside=d.getMonth()!==m,today=di===iso(new Date()),weekStart=dayIndex%7===0,weekEnd=dayIndex%7===6;return`<div class="monthDay ${outside?'outside':''} ${today?'today':''}" data-day="${di}"><div class="dayNo">${d.getDate()}</div>${shown.map(b=>{let bookingStart=b.date,bookingEnd=b.endDate||b.date,isStart=di===bookingStart||weekStart,isEnd=di===bookingEnd||weekEnd,part=isStart&&isEnd?'single':isStart?'rangeStart':isEnd?'rangeEnd':'rangeMiddle',label=isStart?eventLabel(b):'&nbsp;';return`<button class="monthEvent ${calendarState(b)} ${part}" title="${esc(eventLabel(b))} · ${esc(b.trainer)}">${label==='&nbsp;'?label:esc(label)}</button>`}).join('')}${items.length>3?`<div class="monthMore">+${items.length-3} weitere</div>`:items.length===0?'<div class="emptyDay">frei</div>':''}</div>`}).join('');
  calendarShell(new Intl.DateTimeFormat('de-DE',{month:'long',year:'numeric'}).format(first),`<div class="monthGrid">${heads}${cells}</div><div id="dayDetails" class="monthList"></div>`);
  $('#prev').onclick=()=>{calendarCursor=new Date(y,m-1,1,12);calendarView()};$('#next').onclick=()=>{calendarCursor=new Date(y,m+1,1,12);calendarView()};
  cont.querySelectorAll('[data-day]').forEach(cell=>cell.onclick=()=>showDay(cell.dataset.day));
}
function showDay(day){let items=bookings.filter(b=>bookingOnDay(b,day)).sort((a,b)=>a.from.localeCompare(b.from)),el=$('#dayDetails');let labels={requested:'ANGEFRAGT',reserved:'RESERVIERT',inuse:'IN NUTZUNG',overdue:'ÜBERFÄLLIG',past:'VERGANGEN',autoClosed:'⚠ AUTOMATISCH ABGESCHLOSSEN',blocked:'GESPERRT / WERKSTATT'};el.innerHTML=`<h3>${fmt(day)}</h3>${items.map(b=>{let state=calendarState(b);return`<article class="calendarDetailCard state-${state}" data-calendar-state="${state}"><span class="calendarDetailStatus">${labels[state]||state}</span><h3>${esc(eventLabel(b))}</h3><p>${esc(b.from)}–${esc(b.to)} · ${esc(b.trainer)}<br><span>${esc(b.purpose||'')}</span></p>${autoClosedInfo(b)}${(admin()||(b.trainerUid===me.uid&&(b.status==='requested'||(b.status==='reserved'&&!tripForBooking(b.id)&&!b.tripStatus))))&&b.status!=='blocked'?`<div class="actions"><button class="dangerBtn" data-delbooking="${b.id}">${b.status==='reserved'?'Reservierung löschen':'Anfrage zurückziehen'}</button></div>`:''}</article>`}).join('')||'<article class="calendarDetailCard state-free"><h3>Alle Busse nach aktueller Datenlage frei</h3></article>'}`;el.querySelectorAll('[data-delbooking]').forEach(btn=>btn.onclick=async e=>{e.stopPropagation();let b=bookings.find(x=>x.id===btn.dataset.delbooking);if(!b)return;if(!admin()&&b.status==='reserved'&&(tripForBooking(b.id)||b.tripStatus))return toast('Diese Fahrt wurde bereits gestartet. Die Reservierung kann nicht mehr gelöscht werden.');if(!confirm(`${b.status==='reserved'?'Reservierung wirklich löschen? Der Bus ist danach für diesen Zeitraum wieder frei.':'Anfrage wirklich zurückziehen?'}`))return;try{await deleteDoc(doc(db,'bookings',b.id));toast(b.status==='reserved'?'Reservierung gelöscht. Bus ist wieder frei.':'Anfrage zurückgezogen');showDay(day)}catch(x){toast(x.message)}});el.scrollIntoView({behavior:'smooth',block:'nearest'})}
function vehicleForm(id){let v=vehicles.find(x=>x.id===id),docBooking=null;if(!admin()){open(`<h2>${esc(v.name)} · ${esc(v.plate)}</h2><p>Die Fahrtdokumentation kann nur vom eingetragenen Fahrer bzw. bei einem externen Fahrer vom Anfragesteller bis 24 Stunden nach Fahrtende bearbeitet werden.</p><button type="button" class="vehicleHistoryBtn" id="vehicleHistoryBtn">Fzg.-Historie anzeigen</button>`);$('#vehicleHistoryBtn').onclick=()=>historyView(id);return;}open(`<h2>${esc(v.name)} · ${esc(v.plate)}</h2><button type="button" class="vehicleHistoryBtn" id="vehicleHistoryBtn">Fzg.-Historie anzeigen</button><form id="vf"><div class="formGrid"><label>Kennzeichen<input name="plate" value="${esc(v.plate)}" ${admin()?'':'disabled'}></label><label>TÜV fällig<input name="tuv" class="narrowDate" type="month" value="${esc(tuvMonthValue(v.tuv))}" ${admin()?'':'disabled'}></label><label>KM Abfahrt<input name="start" type="number" value="${v.km||0}" required></label><label>KM Ankunft<input name="end" type="number" value="${v.km||0}" required></label></div><label>Parkplatz / Standort nach Nutzungsende<input name="location" value="${esc(v.currentLocation||'')}" placeholder="z. B. Vereinsgelände, Parkplatz 3" required></label><div class="toggles">${[['fueled','Getankt'],['cleaned','Geputzt'],['washed','Gewaschen'],['flashed','Geblitzt']].map(([k,l])=>`<button type="button" class="toggle ${v[k]?'on':''}" data-t="${k}">${v[k]?'✓ ':''}${l}</button>`).join('')}</div><label>Schäden / Mängel<textarea name="damage"></textarea></label>${admin()?`<h3>Werkstatt / Sperre</h3><div class="formGrid"><label>Von<input name="workFrom" class="narrowDate" type="date"></label><label>Bis<input name="workTo" class="narrowDate" type="date"></label></div><label>Grund<input name="reason"></label>`:''}<button type="submit" class="primary" id="saveVehicleData">Dokumentation speichern</button></form>`);$('#vehicleHistoryBtn').onclick=()=>historyView(id);let flags={fueled:!!v.fueled,cleaned:!!v.cleaned,washed:!!v.washed,flashed:!!v.flashed};mb.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{flags[b.dataset.t]=!flags[b.dataset.t];b.classList.toggle('on',flags[b.dataset.t]);b.textContent=(flags[b.dataset.t]?'✓ ':'')+({fueled:'Getankt',cleaned:'Geputzt',washed:'Gewaschen',flashed:'Geblitzt'}[b.dataset.t])});$('#vf').onsubmit=async e=>{e.preventDefault();let form=e.target,btn=$('#saveVehicleData'),f=new FormData(form),start=Number(f.get('start')),end=Number(f.get('end')),damage=String(f.get('damage')||'').trim(),location=String(f.get('location')||'').trim();if(!Number.isFinite(start)||!Number.isFinite(end))return toast('Bitte gültige Kilometerstände eingeben.');if(end<start)return toast('KM Ankunft darf nicht kleiner sein.');if(!location)return toast('Bitte Parkplatz oder Standort eintragen.');btn.disabled=true;btn.textContent='Wird gespeichert …';try{let vehicleData={km:end,currentLocation:location,...flags,openDamage:(v.openDamage||0)+(damage?1:0),updatedAt:serverTimestamp()};if(admin()){vehicleData.plate=String(f.get('plate')||'').trim();vehicleData.tuv=String(f.get('tuv')||'')}await updateDoc(doc(db,'vehicles',id),vehicleData);let historySaved=true;try{if(damage)await addDoc(collection(db,'damages'),{vehicleId:id,text:damage,status:'open',reportedBy:me.name,reportedByUid:me.uid,km:end,location,createdAt:serverTimestamp()});if(admin()&&f.get('workFrom'))await addDoc(collection(db,'bookings'),{vehicleId:id,team:'Verein',trainer:me.name,date:f.get('workFrom'),endDate:f.get('workTo')||f.get('workFrom'),from:'00:00',to:'23:59',status:'blocked',purpose:f.get('reason')||'Werkstatt / Sperre',createdAt:serverTimestamp()})}catch(historyError){historySaved=false;console.error('Zusatzdaten konnten nicht gespeichert werden',historyError)}open(`<div class="saveSuccess"><div class="saveSuccessIcon">✓</div><h2>Fahrzeugdaten gespeichert</h2><p>Der Parkplatz/Standort <b>${esc(location)}</b> wurde gespeichert.</p>${historySaved?'':`<p class="saveWarning">Hinweis: Der Verlauf konnte wegen fehlender Berechtigung nicht vollständig ergänzt werden.</p>`}<button type="button" class="primary" id="saveSuccessClose">OK</button></div>`);$('#saveSuccessClose').onclick=()=>modal.close()}catch(x){console.error('Speichern fehlgeschlagen',x);btn.disabled=false;btn.textContent='Dokumentation speichern';toast('Speichern fehlgeschlagen: '+(x?.code||x?.message||'Unbekannter Fehler'))}}}

function historyView(id){let v=vehicles.find(x=>x.id===id),ts=trips.filter(x=>x.vehicleId===id).sort((a,b)=>((b.updatedAt||b.createdAt)?.seconds||0)-((a.updatedAt||a.createdAt)?.seconds||0)),ds=damages.filter(x=>x.vehicleId===id).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)),master=role==='master';open(`<h2>Fzg.-Historie · ${esc(v?.name||'Bus')}</h2><button type="button" class="historyBackBtn" id="historyBackBtn">← Zurück zu Busdetails</button><div class="historyPanel"><h3>Fahrtdokumentation</h3>${ts.length?ts.map(t=>`<div class="historyItem ${t.status==='auto-closed'?'historyWarning':''}"><b>${esc(t.driverName||t.trainer||'')}</b>${t.status==='auto-closed'?`<div class="historyAlert">⚠ Nicht ordnungsgemäß abgeschlossen</div>`:''}<div><b>Fahrt:</b> ${t.date?fmt(t.date):'–'}${t.date&&(t.endDate||t.date)!==t.date?` bis ${fmt(t.endDate)}`:''}${t.from||t.to?` · ${esc(t.from||'')}–${esc(t.to||'')}`:''}</div><div><b>Gestartet:</b> ${esc(fmtTimestamp(t.startedAt||t.createdAt))}</div><div><b>Zuletzt geändert:</b> ${esc(fmtTimestamp(t.updatedAt||t.createdAt))}</div><div><b>Geändert von:</b> ${esc(t.updatedByName||t.trainer||'System')}</div>${t.status==='auto-closed'?`<div><b>Automatisch abgeschlossen:</b> ${esc(fmtTimestamp(t.endedAt||t.updatedAt))}</div><div><b>Letzter Fahrer:</b> ${esc(t.lastDriverName||t.driverName||'Unbekannt')}</div><div><b>KM Ankunft automatisch übernommen:</b> ${Number(t.kmEnd||0).toLocaleString('de-DE')} km</div><div><b>Automatischen Abschluss ausgelöst durch:</b> ${esc(t.autoCloseTriggeredBy||t.updatedByName||'Unbekannt')}</div><div>Fahrzeugzustand und Rückgabeinformationen nicht vollständig dokumentiert.</div>`:''}<div>${Number(t.kmStart||0).toLocaleString('de-DE')} → ${t.kmEnd==null?'offen':Number(t.kmEnd).toLocaleString('de-DE')} km${t.kmEnd!=null?` · gefahren: ${Number(t.distance||0).toLocaleString('de-DE')} km`:''}</div>${t.endLocation?`<div><b>Parkplatz/Standort:</b> ${esc(t.endLocation)}</div>`:''}${t.damageText?`<div class="historyDamage">Schaden: ${esc(t.damageText)}</div>`:''}${master?`<button class="dangerBtn historyDeleteBtn" data-deltrip="${t.id}">Eintrag löschen</button>`:''}</div>`).join(''):'<p>Noch keine Fahrtdokumentation vorhanden.</p>'}<h3>Schäden / Mängel</h3>${ds.length?ds.map(d=>`<div class="historyItem"><b>${esc(d.status||'open')}</b><div>${esc(d.text||'')}</div><div>${Number(d.km||0).toLocaleString('de-DE')} km · ${esc(d.reportedBy||'')}</div><div><b>Erfasst:</b> ${esc(fmtTimestamp(d.createdAt))}</div>${master?`<button class="dangerBtn historyDeleteBtn" data-deldamage="${d.id}">Eintrag löschen</button>`:''}</div>`).join(''):'<p>Keine Schäden dokumentiert.</p>'}</div>`);$('#historyBackBtn').onclick=()=>vehicleForm(id);if(master){mb.querySelectorAll('[data-deltrip]').forEach(b=>b.onclick=async()=>{if(!confirm('Diesen Historieneintrag wirklich löschen?'))return;if(!confirm('ACHTUNG: Der Eintrag wird endgültig gelöscht und kann nicht wiederhergestellt werden. Wirklich löschen?'))return;try{await deleteDoc(doc(db,'trips',b.dataset.deltrip));toast('Historieneintrag gelöscht');setTimeout(()=>historyView(id),100)}catch(e){toast('Löschen fehlgeschlagen: '+(e.message||e))}});mb.querySelectorAll('[data-deldamage]').forEach(b=>b.onclick=async()=>{if(!confirm('Diesen Schadenseintrag wirklich löschen?'))return;if(!confirm('ACHTUNG: Der Eintrag wird endgültig gelöscht und kann nicht wiederhergestellt werden. Wirklich löschen?'))return;try{await deleteDoc(doc(db,'damages',b.dataset.deldamage));toast('Schadenseintrag gelöscht');setTimeout(()=>historyView(id),100)}catch(e){toast('Löschen fehlgeschlagen: '+(e.message||e))}})}}
function code(){const a='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';return Array.from({length:6},()=>a[Math.floor(Math.random()*a.length)]).join('')}
function userView(){if(role!=='master')return;cont.innerHTML=`<div class="user-heading-row"><div class="user-heading-copy"><h2>Benutzerverwaltung</h2><p>Einladungen, Adminrechte und Benutzerzugänge verwalten.</p></div><button id="newInvite" class="primary">+ Einladung</button></div><h3>Offene Einladungen</h3><div class="list">${invites.filter(i=>i.active===true&&!i.used).map(i=>`<div class="item" style="border-color:#f6c900"><b>${esc(i.name)}</b><br>${esc(i.email)}<br>Code: <b>${esc(i.id)}</b><div class="actions"><button data-copy="${i.id}">Code kopieren</button><button data-delinvite="${i.id}">Einladung löschen</button></div></div>`).join('')||'<p>Keine offenen Einladungen.</p>'}</div><h3>Registrierte Benutzer</h3><div class="list">${users.map(u=>`<div class="item ${u.active===false?'userInactive':''}"><div class="row userRow"><div><b>${esc(u.name)}</b><br><small>${esc(u.email)} · ${u.role==='master'?'Admin-Admin':u.role==='admin'?'Admin':'Trainer'}${u.active===false?' · GESPERRT':''}</small></div>${u.role!=='master'?`<div class="actions userActions"><button class="primary" data-role="${u.id}" data-next="${u.role==='admin'?'user':'admin'}">${u.role==='admin'?'Admin entfernen':'Zum Admin machen'}</button><button data-active="${u.id}" data-nextactive="${u.active===false?'true':'false'}">${u.active===false?'Entsperren':'Sperren'}</button><button class="dangerBtn" data-deluser="${u.id}">Benutzer löschen</button></div>`:''}</div></div>`).join('')}</div>`;$('#newInvite').onclick=inviteForm;cont.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.dataset.copy);toast('Code kopiert')});cont.querySelectorAll('[data-delinvite]').forEach(b=>b.onclick=()=>{if(confirm('Einladung wirklich löschen?'))deleteDoc(doc(db,'invites',b.dataset.delinvite))});cont.querySelectorAll('[data-role]').forEach(b=>b.onclick=async()=>{let u=users.find(x=>x.id===b.dataset.role),makeAdmin=b.dataset.next==='admin';if(!confirm(makeAdmin?`${u?.name||'Benutzer'} wirklich zum Admin machen?\n\nAdmins dürfen Reservierungen verwalten und Fahrzeuge bearbeiten.`:`Adminrechte von ${u?.name||'Benutzer'} wirklich entfernen?`))return;try{await updateDoc(doc(db,'users',b.dataset.role),{role:b.dataset.next});toast(makeAdmin?'Adminrechte vergeben':'Adminrechte entfernt')}catch(x){toast(x.message)}});cont.querySelectorAll('[data-active]').forEach(b=>b.onclick=async()=>{let u=users.find(x=>x.id===b.dataset.active),activate=b.dataset.nextactive==='true';if(!confirm(`${u?.name||'Benutzer'} wirklich ${activate?'entsperren':'sperren'}?`))return;try{await updateDoc(doc(db,'users',b.dataset.active),{active:activate});toast(activate?'Benutzer entsperrt':'Benutzer gesperrt')}catch(x){toast(x.message)}});cont.querySelectorAll('[data-deluser]').forEach(b=>b.onclick=async()=>{let u=users.find(x=>x.id===b.dataset.deluser);if(!confirm(`${u?.name||'Benutzer'} wirklich aus der App löschen?\n\nDas bestehende Anmeldekonto bleibt erhalten. Bei einer neuen Einladung verwendet der Benutzer sein bisheriges Passwort.`))return;try{await deleteDoc(doc(db,'users',b.dataset.deluser));toast('App-Zugang gelöscht. Anmeldekonto bleibt erhalten.')}catch(x){toast(x.message)}})}
function inviteForm(){let c=code();open(`<h2>Benutzer einladen</h2><form id="if"><label>Name<input name="name" required></label><label>E-Mail<input name="email" type="email" required></label><label>Einladungscode<input name="code" value="${c}" required maxlength="10"></label><button class="primary">Einladung anlegen</button></form>`);$('#if').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),c=f.get('code').trim().toUpperCase();await setDoc(doc(db,'invites',c),{name:f.get('name').trim(),email:f.get('email').trim().toLowerCase(),active:true,used:false,createdBy:me.uid,createdAt:serverTimestamp()});modal.close();toast('Einladung angelegt')}}
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));
